export function rollingStoneDecade(decade: number): RollingStoneAlbum[] {
  return RS_500_ALBUMS.filter(
    (entry) => entry.year > 0 && Math.floor(entry.year / 10) * 10 === decade,
  );
}

export function rollingStoneGenres(): string[] {
  const counts = new Map<string, number>();
  for (const entry of RS_500_ALBUMS) {
    for (const genre of entry.genres) counts.set(genre, (counts.get(genre) ?? 0) + 1);
  }
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([genre]) => genre);
}

export function rollingStoneItem(entry: RollingStoneAlbum): MusicCatalogItem {
  return {
    kind: "album",
    id: entry.id ? `deezer:album:${entry.id}` : `rs:album:${entry.rank}`,
    connectorId: "catalog",
    title: entry.album,
    artist: entry.artist,
    artwork: entry.cover,
    year: entry.year || undefined,
  };
}

export function rollingStoneItems(filter: {
  decade?: number | null;
  genre?: string | null;
}): MusicCatalogItem[] {
  const { decade = null, genre = null } = filter;
  return RS_500_ALBUMS.filter(
    (entry) =>
      (decade === null || (entry.year > 0 && Math.floor(entry.year / 10) * 10 === decade)) &&
      (genre === null || entry.genres.includes(genre)),
  ).map(rollingStoneItem);
}

export function rollingStoneNeedsSearch(id: string): boolean {
  return id.startsWith("rs:album:");
}
